CREATE TABLE reservation_documents(id VARCHAR2(36) PRIMARY KEY,trip_id VARCHAR2(36) NOT NULL,owner_id VARCHAR2(36) NOT NULL,object_key VARCHAR2(100) NOT NULL,mime_type VARCHAR2(100) NOT NULL,size_bytes NUMBER(12) NOT NULL,status VARCHAR2(20) NOT NULL CHECK(status IN ('UPLOADED','EXTRACTED','CONFIRMED')),extraction CLOB,created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,version NUMBER(19) DEFAULT 0 NOT NULL);
CREATE INDEX reservation_docs_trip ON reservation_documents(trip_id);
CREATE TABLE reservations(id VARCHAR2(36) PRIMARY KEY,document_id VARCHAR2(36) UNIQUE NOT NULL REFERENCES reservation_documents(id),trip_id VARCHAR2(36) NOT NULL,provider VARCHAR2(200) NOT NULL,reference VARCHAR2(100) NOT NULL,timezone VARCHAR2(80) NOT NULL,starts_at TIMESTAMP WITH TIME ZONE NOT NULL,ends_at TIMESTAMP WITH TIME ZONE NOT NULL,created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,version NUMBER(19) DEFAULT 0 NOT NULL,CHECK(ends_at>starts_at));
CREATE INDEX reservations_trip ON reservations(trip_id,starts_at);
